package com.manggome.oneemu.library

import java.io.File
import java.io.InputStream
import java.util.zip.GZIPInputStream
import java.util.zip.ZipFile

/**
 * Arcade ROM doctor: compares a MAME zip against the reference set of one of the bundled MAME cores
 * (coreassets/<coreId>/romdb.tsv.gz, generated by cores/<coreId>/gen-romdb.py) and explains what is
 * missing. Pure JVM — no Android types — so it is unit-testable; [ArcadeRomChecker] adds the asset
 * loading, caching and Korean texts, [ArcadeCoreRouter] turns the result into a core choice.
 *
 * Matching follows MAME file loading: every file is looked up in the game zip, then up the `romof`
 * chain (parent zip, BIOS zip). A file is satisfied when an entry with the same CRC (and size) exists
 * anywhere in that chain; an entry with the right name but another CRC counts as a mismatch. Two rules
 * mirror what MAME's `Required files are missing` actually checks:
 *  - BIOS: of a set's `<biosset>`s only the *default* one is loaded ([Game.defaultBios]; `default="yes"`, or the
 *    first biosset when none is marked — stvbios in 0.289), so exactly its files plus every file without a biosset
 *    are required. A romdb without the column falls back to "any one BIOS file present".
 *  - Devices: ROM-carrying devices ([Game.devices], e.g. `segabill` for ST-V) load their files from `<device>.zip`
 *    first and then the game's own search path (game, parent, BIOS zips) — MAME logs
 *    `epr-18022.ic2 NOT FOUND (tried in segabill twcup98 stvbios)`. A missing device zip is [Status.NEEDS_DEVICE].
 *
 * [resolve] looks the zip up in several DBs (one per core, in preference order) with [routeByName]: the
 * first DB wins unless it rates the game's driver "preliminary" (or the driver is known to crash, see
 * [UNSTABLE_DRIVERS]) and a later DB rates it no worse. When no DB knows the file name it falls back to
 * CRC identification: newer MAME versions renamed many sets (rbisland vs rainbow, spidman vs spidey …),
 * so the zip's entry CRCs are matched against every game's ROM list and the best fit is reported as
 * [Status.RENAME_SUGGESTED].
 */
object ArcadeRomCheck {
    enum class Status {
        OK, MISSING_FILES, WRONG_SET, NEEDS_PARENT, NEEDS_BIOS,
        /** A device ROM zip (e.g. segabill.zip) that owns missing files is absent from the folder. */
        NEEDS_DEVICE,
        NEEDS_SAMPLES, CHD_UNSUPPORTED, NOT_IN_DAT, RENAME_SUGGESTED,
        /** The DAT lists the name but carries no per-file data (zip-level only DB, e.g. current MAME): nothing to compare. */
        UNVERIFIED,
    }

    /** `<driver status>` of a game in one core's DAT, normalised by gen-romdb.py (0.78's "protection" = PRELIMINARY). */
    enum class DriverStatus(val rank: Int) {
        /** No `<driver>` element (BIOS sets) or an old romdb without the column: treated like GOOD for routing. */
        UNKNOWN(2), GOOD(2), IMPERFECT(1), PRELIMINARY(0);

        companion object {
            fun parse(s: String): DriverStatus = when (s) {
                "good" -> GOOD
                "imperfect" -> IMPERFECT
                "preliminary", "protection" -> PRELIMINARY
                else -> UNKNOWN
            }
        }
    }

    /**
     * Driver source files (without ".c") that crash natively on arm64 in a core even where its DAT rates the
     * game good — the ST-V/SH-2 emulation (Tecmo World Cup '98 & co.), which kills the whole process in
     * MAME 2003-Plus (0.78) *and* MAME 2010 (0.139). For routing these count as worse than PRELIMINARY in that
     * core; when every core that lists the game crashes, the newest one is still chosen (least-bad bet) and the
     * result carries [Routing.knownUnstable] so the UI can warn before launching.
     */
    val UNSTABLE_DRIVERS: Map<String, Set<String>> = mapOf(
        ArcadeCoreRouter.MAME2003PLUS to setOf("stv", "stvinit", "stvhacks"),
        ArcadeCoreRouter.MAME2010 to setOf("stv"),
        // Current MAME (ArcadeCoreRouter.MAME) has no entry: its ST-V driver runs, so every ST-V game it lists goes there.
    )

    /** Why [routeByName] passed over an earlier (preferred) core. */
    enum class RouteReason {
        /** The first core that lists the game (or the only one) — nothing to explain. */
        NONE,
        /** The preferred core's DAT marks the game preliminary; the chosen core rates it no worse. */
        PREFERRED_PRELIMINARY,
        /** The preferred core's driver is in [UNSTABLE_DRIVERS]; the chosen core rates the game no worse. */
        PREFERRED_UNSTABLE,
    }

    /** Result of [routeByName]: the core to run the game with, and the core it was taken away from (if any). */
    data class Routing(val coreId: String, val game: Game, val reason: RouteReason = RouteReason.NONE, val skippedCoreId: String? = null) {
        /** The chosen core is itself known to crash on this driver ([UNSTABLE_DRIVERS]) — nothing better exists. */
        val knownUnstable: Boolean get() = isUnstableDriver(coreId, game)
    }

    /** Badge colour class for the library list. */
    enum class Severity { OK, WARN, ERROR }

    data class Rom(
        val name: String,
        val size: Long,
        /** lowercase 8-hex CRC32 */
        val crc: String,
        /** null = the game's own file; "=" = same name in the romof set; else the file name in the romof set */
        val merge: String?,
        /** <biosset> name when this file belongs to one selectable BIOS; required only for the set's default biosset */
        val bios: String?,
    ) {
        val merged: Boolean get() = merge != null
        val mergeName: String get() = if (merge == null || merge == "=") name else merge
    }

    data class Game(
        val name: String,
        val description: String,
        val cloneof: String,
        val romof: String,
        /** BIOS set zip short name (e.g. "neogeo") or "" */
        val bios: String,
        val sampleof: String,
        val needsSamples: Boolean,
        val disks: Int,
        val runnable: Boolean,
        val roms: List<Rom>,
        /** Normalised `<driver status>`: "good" | "imperfect" | "preliminary" | "" (unknown / old romdb). */
        val status: String = "",
        /** `<game sourcefile>`, e.g. "stv.c"; "" when unknown. */
        val sourceFile: String = "",
        /** Raw `<driver>` flags for display/diagnosis (0.78: emulation = raw status incl. "protection"). */
        val emulation: String = "",
        val color: String = "",
        val sound: String = "",
        val graphic: String = "",
        /**
         * The `<biosset>` MAME loads when the user picks none (`default="yes"`, else the first biosset — gen-romdb.py
         * resolves that); "" when the set has no biossets or the romdb predates the column.
         */
        val defaultBios: String = "",
        /** Short names of the ROM-carrying devices this machine instantiates (MAME `device_ref`), e.g. ["segabill"]. */
        val devices: List<String> = emptyList(),
    ) {
        /** Files this set ships itself (not merged from a parent/BIOS, not BIOS alternatives). */
        val ownRoms: List<Rom> get() = roms.filter { !it.merged && it.bios == null }
        /**
         * Files MAME loads for this set: everything without a biosset plus the default biosset's files. When the romdb
         * carries no [defaultBios] the biosset files are left out here and [check] falls back to "any one BIOS file".
         */
        val requiredRoms: List<Rom> get() = roms.filter { it.bios == null || (defaultBios.isNotEmpty() && it.bios == defaultBios) }
        /** BIOS-alternative files that are not judged individually (old romdb without a defaultbios column). */
        val legacyBiosRoms: List<Rom> get() = if (defaultBios.isEmpty()) roms.filter { it.bios != null } else emptyList()
        val driverStatus: DriverStatus get() = DriverStatus.parse(status)
        /** "stv" for "stv.c" / "drivers/stv.c". */
        val driverName: String get() = sourceFile.substringAfterLast('/').substringBeforeLast('.').lowercase()
    }

    class Db(private val games: Map<String, Game>) {
        val size: Int get() = games.size
        operator fun get(shortName: String): Game? = games[shortName.lowercase()]

        /** CRC → games listing a ROM with that CRC. Built on first CRC identification only (costs a few MB). */
        private val crcIndex: Map<String, List<Game>> by lazy {
            val map = HashMap<String, MutableList<Game>>(games.size * 8)
            for (g in games.values) for (r in g.roms) map.getOrPut(r.crc) { ArrayList(2) }.add(g)
            map
        }

        /**
         * Finds the game a zip with these entry CRCs most likely is. BIOS sets are never suggested. A game qualifies
         * when all of its own (non-merged) files are present, or when ≥ [minShare] of the zip's entries belong to it
         * and at least half of its own files are there (so one shared BIOS/parent CRC never matches everything).
         * Ties prefer a complete own-file set, more matches, a ROM count close to the zip's, parents over clones, then name.
         */
        fun identify(crcs: Set<String>, minShare: Double = 0.6): Game? {
            if (crcs.isEmpty()) return null
            val hits = HashMap<String, Int>()
            val byName = HashMap<String, Game>()
            for (crc in crcs) for (g in crcIndex[crc] ?: continue) {
                // Count distinct zip CRCs per game (a game may list the same CRC twice).
                hits[g.name] = (hits[g.name] ?: 0) + 1
                byName[g.name] = g
            }
            if (hits.isEmpty()) return null
            val need = kotlin.math.ceil(crcs.size * minShare).toInt().coerceAtLeast(1)
            data class Scored(val game: Game, val matched: Int, val ownShare: Double)
            val candidates = hits.mapNotNull { (name, matched) ->
                val g = byName[name] ?: return@mapNotNull null
                if (!g.runnable) return@mapNotNull null
                val own = g.ownRoms
                val ownMatched = own.count { it.crc in crcs }
                val ownShare = if (own.isEmpty()) 0.0 else ownMatched.toDouble() / own.size
                val complete = own.isNotEmpty() && ownMatched == own.size
                if (complete || (matched >= need && ownShare >= 0.5)) Scored(g, matched, ownShare) else null
            }
            return candidates.sortedWith(
                compareByDescending<Scored> { it.ownShare }
                    .thenByDescending { it.matched }
                    .thenBy { kotlin.math.abs(it.game.roms.size - crcs.size) }
                    .thenByDescending { it.game.cloneof.isEmpty() }
                    .thenBy { it.game.name },
            ).firstOrNull()?.game
        }

        companion object {
            fun parseGzip(input: InputStream): Db = parse(GZIPInputStream(input, 64 * 1024))

            fun parse(input: InputStream): Db {
                val map = HashMap<String, Game>(6000)
                input.bufferedReader(Charsets.UTF_8).useLines { lines ->
                    for (line in lines) {
                        if (line.isEmpty() || line[0] == '#') continue
                        parseLine(line)?.let { map[it.name.lowercase()] = it }
                    }
                }
                return Db(map)
            }

            /**
             * name  description  cloneof  romof  bios  sampleof  needsSamples  disks  runnable  roms
             * [status  sourcefile  emulation  color  sound  graphic  [defaultbios  devices]] — the trailing columns are
             * optional (older romdb files): six driver-status columns, then the default biosset name and the
             * ';'-separated ROM-carrying device names.
             */
            fun parseLine(line: String): Game? {
                val p = line.split('\t')
                if (p.size < 10) return null
                val roms = if (p[9].isEmpty()) emptyList() else p[9].split(';').mapNotNull { tok ->
                    val f = tok.split(':')
                    if (f.size < 3) return@mapNotNull null
                    Rom(
                        name = unescape(f[0]),
                        size = f[1].toLongOrNull() ?: 0L,
                        crc = f[2].lowercase(),
                        merge = f.getOrNull(3)?.takeIf { it.isNotEmpty() }?.let { if (it == "=") it else unescape(it) },
                        bios = f.getOrNull(4)?.takeIf { it.isNotEmpty() }?.let(::unescape),
                    )
                }
                return Game(
                    name = p[0], description = p[1], cloneof = p[2], romof = p[3], bios = p[4], sampleof = p[5],
                    needsSamples = p[6] == "1", disks = p[7].toIntOrNull() ?: 0, runnable = p[8] != "0", roms = roms,
                    status = p.getOrElse(10) { "" }, sourceFile = p.getOrElse(11) { "" }, emulation = p.getOrElse(12) { "" },
                    color = p.getOrElse(13) { "" }, sound = p.getOrElse(14) { "" }, graphic = p.getOrElse(15) { "" },
                    defaultBios = p.getOrElse(16) { "" },
                    devices = p.getOrElse(17) { "" }.takeIf { it.isNotEmpty() }?.split(';')?.filter { it.isNotEmpty() } ?: emptyList(),
                )
            }

            private fun unescape(s: String): String =
                if ('%' !in s) s else s.replace("%3A", ":").replace("%3B", ";").replace("%25", "%")
        }
    }

    /** One file the set lacks ([foundCrc] == null) or has with the wrong content. */
    data class FileIssue(
        val name: String,
        val expectedCrc: String,
        val size: Long,
        val foundCrc: String?,
        /** Short name of the zip that should contain the file (the game itself, its parent, the BIOS set or a device). */
        val owner: String,
    ) {
        val missing: Boolean get() = foundCrc == null
    }

    /** What an owner zip is to the game — for labels such as "segabill.zip: 없음 (장치 롬)". */
    enum class OwnerKind { GAME, PARENT, BIOS, DEVICE }

    data class Report(
        /** The zip's file name (lowercase, no extension) — for RENAME_SUGGESTED this is the wrong/new name. */
        val shortName: String,
        val status: Status,
        val game: Game?,
        val issues: List<FileIssue> = emptyList(),
        /** Parent (split-set) zip short name, when the game is a clone. */
        val parentZip: String? = null,
        val parentPresent: Boolean = false,
        val biosZip: String? = null,
        val biosPresent: Boolean = false,
        val sampleZip: String? = null,
        val samplesPresent: Boolean = false,
        val disks: Int = 0,
        /** Set that is absent and owns missing files (NEEDS_PARENT / NEEDS_BIOS / NEEDS_DEVICE). */
        val neededZip: String? = null,
        /** RENAME_SUGGESTED: the DAT short name this zip should have (== game.name). */
        val suggestedName: String? = null,
        /** Device zips the game loads ROMs from ([Game.devices]), e.g. ["segabill"]. */
        val deviceZips: List<String> = emptyList(),
        /** Zips of the search path (game, parent, BIOS, devices) that exist in the folder — see [zipPresent]. */
        val presentZips: Set<String> = emptySet(),
    ) {
        val missing: List<FileIssue> get() = issues.filter { it.missing }
        val mismatched: List<FileIssue> get() = issues.filter { !it.missing }
        val severity: Severity
            get() = when (status) {
                Status.OK, Status.UNVERIFIED -> Severity.OK
                Status.WRONG_SET, Status.NEEDS_SAMPLES, Status.RENAME_SUGGESTED -> Severity.WARN
                Status.MISSING_FILES, Status.NEEDS_PARENT, Status.NEEDS_BIOS, Status.NEEDS_DEVICE, Status.CHD_UNSUPPORTED, Status.NOT_IN_DAT -> Severity.ERROR
            }

        /** True when `<owner>.zip` exists in the game's folder (the game zip itself counts as present when it exists). */
        fun zipPresent(owner: String): Boolean = owner in presentZips

        fun ownerKind(owner: String): OwnerKind = when {
            owner == (game?.name ?: shortName) -> OwnerKind.GAME
            owner == biosZip -> OwnerKind.BIOS
            owner in deviceZips -> OwnerKind.DEVICE
            else -> OwnerKind.PARENT
        }

        /** Issues grouped by owner zip: the game's own zip first, then parent, BIOS and device zips (stable within a kind). */
        val issuesByOwner: List<Pair<String, List<FileIssue>>>
            get() = issues.groupBy { it.owner }.toList().sortedBy { ownerKind(it.first).ordinal }

        /** Missing files of the BIOS zip while that zip *is* in the folder: the user's BIOS set predates this core's DAT. */
        val outdatedBiosFiles: List<FileIssue>
            get() = biosZip?.takeIf { biosPresent }?.let { b -> missing.filter { it.owner == b } } ?: emptyList()
    }

    /**
     * Result of [resolve]: which core runs the zip ([coreId] null = no DAT lists it) and that core's [report].
     * For RENAME_SUGGESTED the report was produced as if the zip already had `report.suggestedName`.
     * [reason]/[skippedCoreId] say when the game was taken away from an earlier core (see [routeByName]).
     */
    data class Resolution(
        val coreId: String?,
        val report: Report,
        val reason: RouteReason = RouteReason.NONE,
        val skippedCoreId: String? = null,
    ) {
        val status: Status get() = report.status
        /** Driver status of the game in the chosen core's DAT (UNKNOWN when no DAT lists it). */
        val driverStatus: DriverStatus get() = report.game?.driverStatus ?: DriverStatus.UNKNOWN
        /**
         * Independent of [status]: the chosen core is known to crash the process on this game's driver
         * ([UNSTABLE_DRIVERS]) and no bundled core does better. The UI warns before launching.
         */
        val knownUnstable: Boolean get() = coreId != null && report.game?.let { isUnstableDriver(coreId, it) } == true
    }

    /** True when [game] is rated preliminary in [coreId], or its driver is listed in [UNSTABLE_DRIVERS] for that core. */
    fun isUnreliable(coreId: String, game: Game): Boolean =
        game.driverStatus == DriverStatus.PRELIMINARY || isUnstableDriver(coreId, game)

    fun isUnstableDriver(coreId: String, game: Game): Boolean = UNSTABLE_DRIVERS[coreId]?.contains(game.driverName) == true

    /** Effective rating of [game] in [coreId] for routing: a known crash ranks below PRELIMINARY. */
    private fun effectiveRank(coreId: String, game: Game): Int = if (isUnstableDriver(coreId, game)) -1 else game.driverStatus.rank

    /**
     * Picks the core for [shortName] among [dbs] (preference order, e.g. MAME 2003-Plus → MAME 2010):
     *  1. the first DB that lists the name wins when it rates the driver good/imperfect (or has no rating);
     *  2. when it rates the game preliminary — or the driver is in [UNSTABLE_DRIVERS] for that core — the first
     *     later DB that rates the game strictly better takes it; failing that, the **last** later DB that rates it
     *     equally badly (an equal "preliminary" — or an equal known crash — still moves the game: the newer MAME's
     *     driver is the better bet), with the reason recorded;
     *  3. otherwise the first DB keeps the game (nothing better exists).
     * When the chosen core's driver is itself in [UNSTABLE_DRIVERS], [Routing.knownUnstable] is true: the game is
     * expected to crash the process wherever it runs, so callers should warn before launching.
     * With the third DB (current MAME, whose status column may be missing = UNKNOWN = rated like GOOD) this means:
     * a game the first two rate preliminary / crash on (ST-V) goes to `mame` whenever that DB lists it — regardless
     * of whether the (downloadable) core is installed; the caller's download prompt handles that.
     * Returns null when no DB lists the name.
     */
    fun routeByName(dbs: List<Pair<String, Db>>, shortName: String): Routing? {
        val listed = dbs.mapNotNull { (id, db) -> db[shortName]?.let { id to it } }
        val (firstId, first) = listed.firstOrNull() ?: return null
        val reason = when {
            first.driverStatus == DriverStatus.PRELIMINARY -> RouteReason.PREFERRED_PRELIMINARY
            isUnstableDriver(firstId, first) -> RouteReason.PREFERRED_UNSTABLE
            else -> return Routing(firstId, first)
        }
        val firstRank = effectiveRank(firstId, first)
        val later = listed.drop(1)
        val alt = later.firstOrNull { (id, game) -> effectiveRank(id, game) > firstRank }
            ?: later.lastOrNull { (id, game) -> effectiveRank(id, game) == firstRank }
        return if (alt != null) Routing(alt.first, alt.second, reason, firstId) else Routing(firstId, first)
    }

    private class Entry(val crc: String, val size: Long)

    /**
     * @param sibling resolves "<name>.zip" in the game's folder (case-insensitive lookups can be plugged in).
     * @param samplesDir `<system>/<core>/samples`, or null to skip the sample check.
     * @param chdSupported false (MAME 2003-Plus) turns any CHD game into CHD_UNSUPPORTED; true (MAME 2010) checks
     *   the ROM files only and leaves `disks` for the UI to mention.
     * @param asName check the zip as if it were named `<asName>.zip` (CRC identification / rename preview).
     */
    fun check(
        db: Db,
        zip: File,
        samplesDir: File? = null,
        sibling: (String) -> File = { File(zip.parentFile ?: File("."), it) },
        chdSupported: Boolean = false,
        asName: String? = null,
    ): Report {
        val shortName = (asName ?: zip.nameWithoutExtension).lowercase()
        val game = db[shortName] ?: return Report(shortName, Status.NOT_IN_DAT, null)

        // romof chain: game → parent → BIOS
        val chain = ArrayList<Game>()
        var cur: Game? = game
        while (cur != null && chain.none { it.name == cur!!.name }) {
            chain.add(cur)
            cur = cur.romof.takeIf { it.isNotEmpty() }?.let { db[it] }
        }
        val parentZip = game.cloneof.ifEmpty { game.romof.takeIf { it.isNotEmpty() && it != game.bios } }
        val biosZip = game.bios.ifEmpty { null }
        // Devices whose ROMs MAME loads for this machine (the DB lists them as non-runnable entries with rom rows).
        val devices: List<Game> = game.devices.mapNotNull { db[it] }.filter { it.roms.isNotEmpty() && it.name != game.name }
        val zipFiles = LinkedHashMap<String, File>()
        for (g in chain) zipFiles[g.name] = if (g === game) zip else sibling("${g.name}.zip")
        if (biosZip != null && biosZip !in zipFiles) zipFiles[biosZip] = sibling("$biosZip.zip")
        for (d in devices) {
            zipFiles.getOrPut(d.name) { sibling("${d.name}.zip") }
            // A device with a parent ROM device (qsound_hle → qsound) also loads from the parent's zip.
            d.romof.takeIf { it.isNotEmpty() }?.let { zipFiles.getOrPut(it) { sibling("$it.zip") } }
        }
        val present = zipFiles.mapValues { it.value.isFile }
        val presentZips = present.filterValues { it }.keys
        val deviceZips = devices.map { it.name }
        val sampleZip = game.sampleof.ifEmpty { null }
        val samplesPresent = sampleZip != null && samplesDir != null && File(samplesDir, "$sampleZip.zip").isFile

        fun base(status: Status, issues: List<FileIssue> = emptyList(), needed: String? = null) = Report(
            shortName = game.name, status = status, game = game, issues = issues,
            parentZip = parentZip, parentPresent = parentZip != null && present[parentZip] == true,
            biosZip = biosZip, biosPresent = biosZip != null && present[biosZip] == true,
            sampleZip = sampleZip, samplesPresent = samplesPresent, disks = game.disks, neededZip = needed,
            deviceZips = deviceZips, presentZips = presentZips,
        )
        if (game.disks > 0 && !chdSupported) return base(Status.CHD_UNSUPPORTED)
        // Zip-level only DB (no <rom> rows): the name is known, the contents cannot be judged.
        if (game.roms.isEmpty()) return base(Status.UNVERIFIED)

        // Entries of every present zip, keyed by short name (read once, shared by the game and device search paths).
        val entriesOf = HashMap<String, Map<String, Entry>>()
        fun entries(name: String): Map<String, Entry>? {
            val f = zipFiles[name] ?: return null
            if (!f.isFile) return null
            return entriesOf.getOrPut(name) { readEntries(f) }
        }
        // The game's search path: game zip, then up the romof chain (parent, BIOS).
        val chainContents: List<Pair<String, Map<String, Entry>>> = chain.mapNotNull { g -> entries(g.name)?.let { g.name to it } }
        // A device's search path: <device>.zip, its parent ROM device's zip, then the game's search path.
        fun deviceContents(d: Game): List<Pair<String, Map<String, Entry>>> = buildList {
            entries(d.name)?.let { add(d.name to it) }
            d.romof.takeIf { it.isNotEmpty() }?.let { p -> entries(p)?.let { add(p to it) } }
            addAll(chainContents)
        }
        // Device files MAME requires: the device's default-BIOS rule applies to it as to any set.
        fun deviceIssues(missingOnly: Boolean): List<FileIssue> = devices.flatMap { d ->
            val contents = if (missingOnly) emptyList() else deviceContents(d)
            d.requiredRoms.mapNotNull { rom ->
                if (lookup(contents, rom) != null) null
                else FileIssue(rom.name, rom.crc, rom.size, byName(contents, rom)?.crc, d.name)
            }
        }

        if (chainContents.isEmpty() || chainContents.first().first != game.name) {
            // Unreadable / corrupt game zip: everything is missing.
            val all = game.requiredRoms.map { FileIssue(it.name, it.crc, it.size, null, ownerOf(game, chain, it)) } + deviceIssues(missingOnly = true)
            return base(Status.MISSING_FILES, all)
        }

        val issues = ArrayList<FileIssue>()
        for (rom in game.requiredRoms) {
            if (lookup(chainContents, rom) != null) continue
            issues.add(FileIssue(rom.name, rom.crc, rom.size, byName(chainContents, rom)?.crc, ownerOf(game, chain, rom)))
        }
        // Old romdb without a defaultbios column: any one BIOS-alternative file satisfies the set.
        val legacyBios = game.legacyBiosRoms
        if (legacyBios.isNotEmpty() && legacyBios.none { lookup(chainContents, it) != null }) {
            val first = legacyBios.first()
            issues.add(FileIssue(first.name, first.crc, first.size, byName(chainContents, first)?.crc, ownerOf(game, chain, first)))
        }
        issues.addAll(deviceIssues(missingOnly = false))

        if (issues.isEmpty()) {
            return base(if (game.needsSamples && !samplesPresent) Status.NEEDS_SAMPLES else Status.OK)
        }
        val missing = issues.filter { it.missing }
        if (missing.isEmpty()) return base(Status.WRONG_SET, issues)
        val absentOwners = missing.map { it.owner }.distinct().filter { it != game.name && present[it] != true }
        return when {
            biosZip != null && biosZip in absentOwners -> base(Status.NEEDS_BIOS, issues, biosZip)
            absentOwners.any { it in deviceZips } -> base(Status.NEEDS_DEVICE, issues, absentOwners.first { it in deviceZips })
            absentOwners.isNotEmpty() -> base(Status.NEEDS_PARENT, issues, absentOwners.first())
            else -> base(Status.MISSING_FILES, issues)
        }
    }

    /** Exact match by CRC (and size) anywhere in [contents], in search order. */
    private fun lookup(contents: List<Pair<String, Map<String, Entry>>>, rom: Rom): Entry? {
        for ((_, entries) in contents) {
            entries.values.firstOrNull { it.crc == rom.crc && (rom.size == 0L || it.size == rom.size) }?.let { return it }
        }
        return null
    }

    /** Entry with the ROM's name (or its merge name) anywhere in [contents] — what a "right name, wrong CRC" mismatch found. */
    private fun byName(contents: List<Pair<String, Map<String, Entry>>>, rom: Rom): Entry? {
        val names = if (rom.merged && rom.mergeName != rom.name) listOf(rom.name, rom.mergeName) else listOf(rom.name)
        for ((_, entries) in contents) for (n in names) entries[n.lowercase()]?.let { return it }
        return null
    }

    /**
     * Routes [zip] with [routeByName] (first DB in [dbs] order that lists its short name, unless that core rates
     * the driver preliminary/unstable and a later one does no worse) and checks it there. When none lists the
     * name, identifies the set by entry CRCs in the same order, routes the identified name the same way and
     * returns RENAME_SUGGESTED (the report is the check under the suggested name, so missing files are still
     * listed). Otherwise NOT_IN_DAT with `coreId == null`.
     *
     * @param samplesDir per-core samples folder (null = don't judge samples)
     * @param chdSupported per-core CHD capability (see [check])
     */
    fun resolve(
        dbs: List<Pair<String, Db>>,
        zip: File,
        samplesDir: (String) -> File? = { null },
        chdSupported: (String) -> Boolean = { false },
        sibling: (String) -> File = { File(zip.parentFile ?: File("."), it) },
    ): Resolution {
        val shortName = zip.nameWithoutExtension.lowercase()
        val byId = dbs.toMap()
        routeByName(dbs, shortName)?.let { rt ->
            val db = byId.getValue(rt.coreId)
            return Resolution(rt.coreId, check(db, zip, samplesDir(rt.coreId), sibling, chdSupported(rt.coreId)), rt.reason, rt.skippedCoreId)
        }
        val crcs = readEntries(zip).values.mapTo(HashSet()) { it.crc }
        if (crcs.isNotEmpty()) {
            for ((_, db) in dbs) {
                val name = db.identify(crcs)?.name ?: continue
                // The identified name may be rated better in another core: route it like a correctly named zip.
                val rt = routeByName(dbs, name) ?: continue
                val r = check(byId.getValue(rt.coreId), zip, samplesDir(rt.coreId), sibling, chdSupported(rt.coreId), asName = name)
                return Resolution(rt.coreId, r.copy(shortName = shortName, status = Status.RENAME_SUGGESTED, suggestedName = name), rt.reason, rt.skippedCoreId)
            }
        }
        return Resolution(null, Report(shortName, Status.NOT_IN_DAT, null))
    }

    /** Which set in the chain actually ships [rom] (follows merge names up to the first non-merged definition). */
    private fun ownerOf(game: Game, chain: List<Game>, rom: Rom): String {
        if (!rom.merged) return game.name
        var name = rom.mergeName
        for (anc in chain.drop(1)) {
            val target = anc.roms.firstOrNull { it.name.equals(name, ignoreCase = true) } ?: continue
            if (!target.merged) return anc.name
            name = target.mergeName
        }
        return game.bios.ifEmpty { game.romof.ifEmpty { game.name } }
    }

    /** lowercase entry name → CRC/size from the central directory (nothing is inflated). */
    private fun readEntries(file: File): Map<String, Entry> = runCatching {
        ZipFile(file).use { zf ->
            val map = HashMap<String, Entry>()
            for (e in zf.entries()) {
                if (e.isDirectory) continue
                val crc = e.crc
                if (crc < 0) continue
                map[e.name.substringAfterLast('/').lowercase()] = Entry(String.format("%08x", crc), e.size)
            }
            map
        }
    }.getOrDefault(emptyMap())
}
